node -e "
const XLSX = require('xlsx');
const path = 'testbed/data/order_summary.xlsx';
const wb = XLSX.readFile(path);
const ws = wb.Sheets[wb.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

// Find ORD-6C71B1 and update status
const headerRow = data[0];
const orderIdCol = headerRow.indexOf('Order ID');
const statusCol = headerRow.indexOf('Status');

let updated = false;
for (let i = 1; i < data.length; i++) {
  if (data[i][orderIdCol] === 'ORD-6C71B1') {
    const cellRef = XLSX.utils.encode_cell({ r: i, c: statusCol });
    ws[cellRef].v = 'confirmed';
    updated = true;
    break;
  }
}

if (updated) {
  XLSX.writeFile(wb, path);
  console.log('Status updated successfully.');
} else {
  console.log('Order not found.');
}
"

